import csv
import io


def parse_csv(raw_csv: str):
    source = io.StringIO(raw_csv.removeprefix("\ufeff"), newline="")

    # Skip blank lines and metadata comments only before the header.
    while True:
        position = source.tell()
        line = source.readline()
        if not line:
            return {"columns": [], "rows": []}
        if line.strip() and not line.lstrip().startswith("#"):
            source.seek(position)
            break

    reader = csv.reader(source, delimiter=",", quotechar='"', doublequote=True)
    columns = next(reader, [])
    rows = list(reader)

    # Pad short records and give surplus fields their own columns.
    width = max(5, len(columns), max(map(len, rows), default=0))
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
